<template><SuperAdminLayout><main class="cas"><header><h1>Customers Centre <span>›</span> Customer Account Status Report</h1><RouterLink to="/super-admin/customers">←　Back to Customers Centre</RouterLink></header><form @submit.prevent="load"><h2>Filter</h2><label>Status<select v-model="f.status"><option>All</option><option>Active</option><option>Inactive</option></select></label><label>Date From<input v-model="f.from" type="date"></label><label>Date To<input v-model="f.to" type="date"></label><label>Customer No.<input v-model="f.customer" placeholder="Enter Customer No."></label><label>Company Name<input v-model="f.company" placeholder="Enter Company Name"></label><label>Plan<select v-model="f.plan"><option>All Plan</option></select></label><div><button>Search</button><button type="button" @click="reset">Reset</button></div></form><section class="summary"><h2>Summary (As of {{today}})</h2><article v-for="x in cards" :key="x.label" :class="x.class"><span>{{x.label}}</span><strong>{{x.value}}</strong></article></section><section class="tablebox"><h2>Customer Account Status Details</h2><table><thead><tr><th>No.</th><th>Customer No.</th><th>Company Name</th><th>Status</th><th>Status From Date</th><th>Reason</th><th>Changed By</th><th>Change Date</th><th>Reactivation Date</th><th>View Profile</th></tr></thead><tbody><tr v-for="(r,i) in shown" :key="r.customer_no"><td>{{i+1}}</td><td>{{r.customer_no}}</td><td>{{r.company}}</td><td><b :class="status(r.status)">{{r.status}}</b></td><td>{{date(r.since)}}</td><td>—</td><td>System</td><td>{{date(r.last_activity)}}</td><td>—</td><td><RouterLink :to="'/super-admin/customers/'+id(r.customer_no)">View</RouterLink></td></tr></tbody><tfoot><tr><th>Total</th><th>{{shown.length}}</th><th></th><th>{{active}}</th><th></th><th></th><th></th><th></th><th></th><th></th></tr></tfoot></table><footer>Showing 1 to {{shown.length}} of {{shown.length}} records <span>‹　<b>1</b>　›</span></footer></section><div class="bottom"><button @click="print">▣　Print</button><button @click="print">▧　Save PDF</button><p>ⓘ　All dates are shown in your system time zone.</p></div></main></SuperAdminLayout></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{RouterLink}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const all=ref([]),f=reactive({status:'All',from:'',to:'',customer:'',company:'',plan:'All Plan'}),today=new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',year:'numeric'}).format(new Date()),date=v=>v?new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',year:'numeric'}).format(new Date(v)):'—',id=v=>String(v||'').replace(/\D/g,''),status=v=>String(v).toLowerCase(),shown=computed(()=>all.value.filter(x=>(f.status==='All'||x.status===f.status)&&(!f.company||x.company.toLowerCase().includes(f.company.toLowerCase()))&&(!f.customer||x.customer_no.includes(f.customer)))),active=computed(()=>shown.value.filter(x=>x.status==='Active').length),cards=computed(()=>[{label:'Total Customers',value:shown.value.length},{label:'Active',value:active.value,class:'green'},{label:'Inactive',value:shown.value.filter(x=>x.status==='Inactive').length},{label:'Suspended',value:0,class:'orange'},{label:'Payment Suspended',value:0,class:'red'},{label:'Violation',value:0,class:'red'},{label:'Closed',value:0}]);async function load(){all.value=(await client.get('/super-admin/reports/account-status')).data.data.rows||[]}function reset(){Object.assign(f,{status:'All',from:'',to:'',customer:'',company:'',plan:'All Plan'});load()}function print(){window.print()}onMounted(load)</script>
<style>.cas{color:#071541}.cas header{display:flex;justify-content:space-between;align-items:center}.cas h1{font-size:2rem;margin:8px 0 15px;font-weight:800}.cas h1 span{margin:0 13px}.cas a{color:#0049e5;text-decoration:none;font-weight:700}.cas header a{border:1px solid #d5dfec;border-radius:5px;padding:10px 14px;color:#071541;font-size:.75rem}.cas form,.summary,.tablebox{border:1px solid #dbe4ef;border-radius:6px;background:#fff;padding:14px;margin-bottom:15px}.cas form{display:grid;grid-template-columns:repeat(5,1fr);gap:14px 25px}.cas form h2,.summary h2,.tablebox h2{grid-column:1/-1;margin:0;color:#0647d2;font-size:1rem}.cas label{display:grid;gap:7px;font-size:.75rem;font-weight:700}.cas input,.cas select{height:38px;border:1px solid #ccd9ed;border-radius:4px;padding:0 10px;font:inherit}.cas form div{display:flex;gap:10px;align-items:end}.cas button{height:37px;border:1px solid #d1ddec;border-radius:4px;background:#fff;color:#0645d0;font-weight:700;padding:0 20px}.cas form button:first-child,.bottom button:first-child{background:#0647d2;color:#fff;border-color:#0647d2}.summary{display:grid;grid-template-columns:repeat(7,1fr);gap:16px}.summary h2{margin-bottom:-6px}.summary article{border:1px solid #dde6f0;border-radius:5px;padding:14px}.summary span{font-size:.75rem}.summary strong{display:block;font-size:1.55rem;margin-top:13px}.green strong{color:#087b2f}.orange strong{color:#f07800}.red strong{color:#ec1515}.tablebox{padding:0;overflow:auto}.tablebox h2{padding:12px 15px}.tablebox table{width:100%;min-width:1100px;border-collapse:collapse;font-size:.75rem}.tablebox th,.tablebox td{padding:10px;border:1px solid #e2e9f1;text-align:center}.tablebox th{background:#f4f6f9}.tablebox b{padding:4px 6px;border-radius:3px}.tablebox b.active{background:#dff7e5;color:#08772c}.tablebox b.inactive{background:#edf0f5}.tablebox footer{padding:12px 15px}.tablebox footer span{float:right}.bottom{display:flex;gap:20px;align-items:center}.bottom p{margin-left:auto;background:#f3f7fd;padding:12px 20px;font-size:.75rem}@media(max-width:900px){.cas form,.summary{grid-template-columns:repeat(2,1fr)}}
</style>
